-- Generated by platform/tools/convert.py: references to the public schema were
-- rewritten to `lms`; private schemas renamed app_private -> lms_private.
-- Edit the source app's migration history only until the cutover; after that, edit here.

SET search_path TO lms, extensions;

-- Reversible curriculum visibility. A Lesson is archived independently of its
-- draft/published state; hiding a Track also hides its Lessons from learners.
ALTER TABLE lms.modules
  ADD COLUMN archived_at timestamptz,
  ADD COLUMN hidden_at timestamptz;

ALTER TABLE lms.modules
  ADD CONSTRAINT modules_archive_only_lessons CHECK (archived_at IS NULL OR parent_id IS NOT NULL),
  ADD CONSTRAINT modules_hide_only_tracks CHECK (hidden_at IS NULL OR parent_id IS NULL);

-- SECURITY DEFINER avoids a self-referential modules RLS policy when checking
-- the parent Track. It returns only a visibility boolean to active app users.
CREATE FUNCTION lms.curriculum_item_visible(target_module_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT lms.is_active_app_user(auth.uid()) AND EXISTS (
    SELECT 1 FROM lms.modules m
    LEFT JOIN lms.modules track ON track.id = m.parent_id
    WHERE m.id = target_module_id
      AND m.is_published AND m.deleted_at IS NULL
      AND m.archived_at IS NULL AND m.hidden_at IS NULL
      AND (m.parent_id IS NULL OR (
        track.id IS NOT NULL AND track.is_published
        AND track.deleted_at IS NULL AND track.hidden_at IS NULL))
  );
$$;
REVOKE ALL ON FUNCTION lms.curriculum_item_visible(uuid) FROM PUBLIC, anon, service_role;
GRANT EXECUTE ON FUNCTION lms.curriculum_item_visible(uuid) TO authenticated;

DROP POLICY IF EXISTS "modules: read published" ON lms.modules;
CREATE POLICY "modules: read published" ON lms.modules
  FOR SELECT TO authenticated
  USING (lms.curriculum_item_visible(id));

DROP POLICY IF EXISTS "module_versions: read current published" ON lms.module_versions;
CREATE POLICY "module_versions: read current published" ON lms.module_versions
  FOR SELECT TO authenticated
  USING (is_current AND lms.curriculum_item_visible(module_id));

-- Keep curriculum managers able to preview archived Lessons. Everyone else
-- must meet the normal visibility and notes-access rules.
CREATE OR REPLACE FUNCTION lms.can_access_module_notes(target_module_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT lms.is_active_app_user(auth.uid()) AND EXISTS (
    SELECT 1 FROM lms.modules m
    WHERE m.id = target_module_id AND m.deleted_at IS NULL AND (
      lms.has_admin_permission('manage_curriculum')
      OR (lms.curriculum_item_visible(m.id) AND
        (lms.can_teach_module(m.id) OR EXISTS (
          SELECT 1 FROM lms.learner_progress p
          WHERE p.learner_id = auth.uid() AND p.module_id = m.id AND p.status = 'completed')))));
$$;
